$INQUIRY_BODY = '{"voucher":"WARWDPGG","productId":19,"phoneNumber":"628783219212","paymentPhoneNumber":"628783219212","productItemId":358,"paymentChannelId":73,"referralCode":"","data":{"userId":"36771930","zoneId":"2055"}}';

function headersToCurl(array $h): array {
    $out = [];
    foreach ($h as $k => $v) $out[] = $k . ': ' . $v;
    return $out;
}

function post(string $url, string $body, array $headers, int $timeout = 30): array {
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, $body);
    curl_setopt($ch, CURLOPT_HTTPHEADER, headersToCurl($headers));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, $timeout);
    curl_setopt($ch, CURLOPT_ENCODING, ''); // cURL negosiasi encoding sendiri
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, false);
    $resp = curl_exec($ch);
    $errno = curl_errno($ch);
    $err = curl_error($ch);
    $code = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    return ['code' => $code, 'resp' => is_string($resp) ? $resp : '', 'errno' => $errno, 'err' => $err];
}

function freshTimestampMs(): string {
    return (string) (int) round(microtime(true) * 1000);
}

$pass = 0; $reject = 0; $other = 0; $reloadFail = 0;
for ($i = 0; $i < $ATTEMPTS; $i++) {
    $n = $i + 1;
    $body = base64_decode($RELOAD_BODIES[$i]);
    $r = post($RELOAD_URL, $body, $RELOAD_HEADERS);
    $token = null;
    if ($r['errno'] === 0 && $r['code'] === 200 && preg_match('/"rresp","([^"]+)"/', $r['resp'], $m)) {
        $token = $m[1];
    } else {
        $reloadFail++;
        echo "#$n reload GAGAL (http {$r['code']}, errno {$r['errno']} {$r['err']}) -> SKIP inquiry\n";
        if ($i < $ATTEMPTS - 1) sleep(random_int(4, 6));
        continue;
    }
    $ih = $INQUIRY_HEADERS;
    $ih['x-captcha-token'] = $token;
    $ih['x-timestamp'] = freshTimestampMs();
    $q = post($INQUIRY_URL, $INQUIRY_BODY, $ih);
    $msg = '';
    if ($q['resp'] !== '') {
        $j = json_decode($q['resp'], true);
        if (is_array($j)) $msg = (string) ($j['message'] ?? '');
    }
    $status = '';
    if ($q['code'] === 400 || $q['code'] === 200) { $pass++; $status = 'LOLOS'; }
    elseif ($q['code'] === 406 || $q['code'] === 429 || $q['code'] >= 500) { $reject++; $status = 'DITOLAK'; }
    else { $other++; $status = 'LAIN'; }
    echo "#$n token " . strlen($token) . " char | inquiry {$q['code']} $status | $msg\n";
    if ($i < $ATTEMPTS - 1) sleep(random_int(4, 6));
}

echo "\n=== RINGKASAN ===\n";
echo "Percobaan : $ATTEMPTS\n";
echo "Reload gagal : $reloadFail\n";
echo "Inquiry LOLOS (400/200, token diterima) : $pass\n";
echo "Inquiry DITOLAK (406/429/5xx) : $reject\n";
echo "Inquiry lain : $other\n";
echo ($reject === 0 && $reloadFail === 0)
    ? "HASIL: LOLOS SEMUA ($pass/$ATTEMPTS) — sama seperti tes live di HP.\n"
    : "HASIL: ADA YANG DITOLAK/GAGAL — lihat baris di atas.\n";
